#!/usr/bin/env python3
"""Build both zero-dependency, fully rendered language versions."""
from pathlib import Path
import json
import hashlib

ROOT = Path(__file__).resolve().parent.parent
BASE = 'https://stpork.github.io'
REPO = 'https://github.com/stpork/mdvu'
RELEASE = REPO + '/releases/tag/v0.4.1'
DOWNLOAD = REPO + '/releases/download/v0.4.1/mdvu-0.4.1-macos.dmg'

def theme_toggle(lang):
    def t(en, ru_text): return ru_text if lang == 'ru' else en
    return f'''<button class="theme-toggle" type="button" data-theme-toggle aria-label="{t('Switch theme','Сменить тему')}" title="{t('Switch theme','Сменить тему')}"><svg class="sun-icon" width="19" height="19" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/></svg><svg class="moon-icon" width="19" height="19" viewBox="0 0 24 24" aria-hidden="true"><path d="M20.5 14A9 9 0 0 1 10 3a9 9 0 1 0 10.5 11Z"/></svg></button>'''

def page(lang):
    ru = lang == 'ru'
    css_version = hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
    js_version = hashlib.sha256((ROOT/'assets/site.js').read_bytes()).hexdigest()[:12]
    theme_version = hashlib.sha256((ROOT/'assets/theme.js').read_bytes()).hexdigest()[:12]
    def t(en, ru_text): return ru_text if ru else en
    url = BASE + ('/ru/' if ru else '/')
    title = t('MDVu — Markdown Viewer & MD File Reader for macOS', 'MDVu — просмотрщик Markdown и MD-файлов для macOS')
    description = t('Fast, native Markdown viewer and .md file reader for macOS. ~3.4 MiB, offline Mermaid, PlantUML and LaTeX math. Free and open source.', 'Быстрый просмотрщик Markdown и MD-файлов для macOS. ~3,4 MiB, Mermaid, PlantUML и формулы LaTeX офлайн. Бесплатно, открытый исходный код.')
    faqs = [
        (t('What is a Markdown viewer?', 'Что такое просмотрщик Markdown?'), t('A Markdown viewer displays plain .md files as formatted documents, with readable headings, tables, code and links. MDVu provides a native Markdown preview on macOS, including offline math and diagram rendering.', 'Просмотрщик Markdown отображает обычные MD-файлы как оформленные документы: с заголовками, таблицами, кодом и ссылками. MDVu даёт нативный просмотр Markdown на macOS, включая локальное отображение формул и диаграмм.')),
        (t('Which Markdown files can I open?', 'Какие Markdown-файлы можно открыть?'), t('MDVu is an MD file viewer for .md, .markdown, .mdown and .mkd documents. Open a README, project documentation or a folder of notes directly from Finder or Terminal. The original Markdown files stay where they are.', 'MDVu открывает документы с расширениями .md, .markdown, .mdown и .mkd. Откройте README, документацию проекта или папку заметок прямо из Finder или Terminal. Исходные Markdown-файлы остаются на своих местах.')),
        (t('Is MDVu an editor?', 'MDVu — это редактор?'), t('MDVu is a dedicated viewer. Write in your favorite editor and keep MDVu beside it: the file watcher refreshes the document when you save. It is made for reading, reviewing and navigating Markdown.', 'MDVu создан для просмотра. Пишите в любимом редакторе, а MDVu держите рядом: при сохранении файла документ обновляется автоматически. Это инструмент для чтения, проверки и навигации по Markdown.')),
        (t('Which Macs are supported?', 'Какие Mac поддерживаются?'), t('macOS 13 Ventura or later, on Apple Silicon and Intel. The DMG contains a Universal app; architecture-specific ZIP archives are also available on GitHub Releases.', 'macOS 13 Ventura и новее, Apple Silicon и Intel. В DMG находится универсальная сборка; отдельные ZIP-архивы для каждой архитектуры доступны в GitHub Releases.')),
        (t('Does it really work offline?', 'Он действительно работает офлайн?'), t('Markdown, math and the bundled diagram engines render locally without a server, account or Java installation. Remote images or other external resources referenced by a document can still use the network. MDVu itself has no telemetry.', 'Markdown, формулы и встроенные движки диаграмм работают локально, без сервера, аккаунта и установки Java. Внешние изображения и другие удалённые ресурсы самого документа могут обращаться к сети. В MDVu нет телеметрии.')),
        (t('Can I open my Obsidian vault?', 'Можно открыть хранилище Obsidian?'), t('Yes. Open a folder or a Markdown file inside your vault. MDVu recognizes .obsidian and .git roots and supports callouts, wikilinks and media embeds. It does not run Obsidian plugins or replicate every vault feature.', 'Да. Откройте папку или Markdown-файл внутри хранилища. MDVu распознаёт корни .obsidian и .git, поддерживает выноски, вики-ссылки и медиа-вставки. Плагины Obsidian не запускаются; полного повторения всех его возможностей нет.')),
        (t('Why might macOS show a first-launch warning?', 'Почему macOS может показать предупреждение при запуске?'), t('The v0.4.1 release is ad-hoc signed, not Apple-notarized. Gatekeeper may ask for an explicit first-launch approval. Download only from the project’s official releases, check the published SHA-256 checksum and follow the installation notes linked below.', 'Релиз v0.4.1 подписан ad-hoc и не прошёл нотариализацию Apple. Gatekeeper может потребовать отдельного разрешения при первом запуске. Скачивайте приложение из официальных релизов, проверяйте опубликованную SHA-256-сумму и следуйте инструкции по установке ниже.')),
        (t('Is it free for commercial use?', 'Можно использовать бесплатно в работе?'), t('Yes. MDVu is released under the MIT license, with no subscription or paid feature tier. Bundled third-party components retain their own licenses, listed in the repository.', 'Да. MDVu распространяется под лицензией MIT, без подписки и платных уровней функций. Встроенные сторонние компоненты сохраняют собственные лицензии, перечисленные в репозитории.')),
    ]
    structured = {'@context':'https://schema.org','@graph':[
        {'@type':'SoftwareApplication','@id':BASE+'/#app','name':'MDVu','url':BASE+'/', 'applicationCategory':'UtilitiesApplication','operatingSystem':'macOS 13.0 or later','softwareVersion':'0.4.1','description':description,'image':BASE+'/assets/mdvu.jpg','screenshot':BASE+'/assets/mdvu.jpg','downloadUrl':DOWNLOAD,'license':'https://opensource.org/license/mit','offers':{'@type':'Offer','price':'0','priceCurrency':'USD'},'author':{'@type':'Person','name':'Finn de Bear','url':'https://github.com/stpork'}},
        {'@type':'WebSite','@id':BASE+'/#website','name':'MDVu','url':BASE+'/','inLanguage':['en','ru']},
        {'@type':'WebPage','@id':url+'#webpage','url':url,'name':title,'description':description,'inLanguage':lang,'isPartOf':{'@id':BASE+'/#website'},'about':{'@id':BASE+'/#app'}}
    ]}
